        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        visited = [[False for _ in range(w)] for _ in range(h)]

        def dfs(x, y):
            stack = [(x, y)]
            while stack:
                cx, cy = stack.pop()
                if not (0 <= cx < h and 0 <= cy < w) or visited[cx][cy] or grid[cx][cy] != '.':
