def generate_grid(A, B):
    if A == 1 and B == 1:
        return "1 1\n#"

    h = 2 * max(A, B)
    w = 2 * min(A, B)

    grid = [['.' for _ in range(w)] for _ in range(h)]

    def paint(row, col, color):
        if row < 0 or row >= h or col < 0 or col >= w or grid[row][col] != '.':
            return False
        grid[row][col] = '#' if color else '.'
        return True

    def backtrack(row, col, count, color):
        if count == 0:
            return True
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if paint(nr, nc, color):
                if backtrack(nr, nc, count - 1, color):
                    return True
                paint(nr, nc, '.')
        return False

    for i in range(0, h, 2):
        if not backtrack(i, 0, A, True):
            return None

    for i in range(1, h, 2):
        if not backtrack(i, 0, B, False):
            return None

    return f"{h} {w}\n" + '\n'.join(''.join(row) for row in grid)

